before:
Complete local Go example; the app itself does not execute it:
```go
package main

import (
"fmt"
"io"
"bytes"
"strings"
)


func main() {
    var dst bytes.Buffer
    n, err := io.Copy(&dst, strings.NewReader("read"))
    if err != nil { panic(err) }
    fmt.Println(n, dst.String())
}
```

